// A transport that comes back after its wisp connection is lost. Epoxy
// never does: when the WebSocket under its wisp multiplexor goes away (a
// port forward, a proxy or a flaky network that drops it), the client keeps
// the dead multiplexor as its connection and its HTTP pool keeps the
// connections that ran over it. A request that needs a new stream fails at
// once with MuxTaskEnded, and one handed a pooled connection over the dead
// multiplexor can wait forever, for the life of the page. Measured: one
// drop 1.5 s into a YouTube load left the page half drawn (the app's
// scripts failed, nothing after the drop loaded) until the host page was
// reloaded.
//
// This wrapper builds a new transport (a new wisp connection and an empty
// pool) the first time a request reports the old connection gone, and sends
// again the requests that cannot have reached the server or that Chrome
// would send again itself: one whose connection was lost while it was being
// opened (its stream or its TLS handshake), and a GET, HEAD or OPTIONS
// without a body that the lost wisp connection took before its response
// head. Such a request still waiting on the old transport when the new one
// is up is sent again too, since nothing will ever answer it there. A
// response whose body was cut off is the page's, as in Chrome. Over a live
// wisp connection, a request the server's close took is epoxy's to send
// again, as Chrome does (a kept connection the server closed as the request
// reached it, whatever the method; a refused HTTP/2 stream; not a fresh
// connection's, nor one whose response had begun: deploy/epoxy patches
// hyper 0052, hyper-util-wasm 0052, epoxy-tls 0073), so what reaches this
// wrapper then is the page's (idle-close-retry suite). Which of the two it
// was is not in the error: a stream the dying wisp connection took ends as
// a server's close does. So a GET lost that way asks the wisp connection
// for a stream (#wispAlive): one it no longer opens means the tunnel went,
// which a native connection never sees, and the GET goes again over a new
// one (wisp-reconnect suite).
//
// Chrome closes a page's WebSockets as it goes into the back/forward cache
// (the page reads a close, 1006, once it is back), the transport worker's
// wisp WebSocket with them, and epoxy's own WebSocket (by URL, not a
// carrier: wispWebTransport.ts) never ends its multiplexor on that close.
// The first request after the host came back went to the site's pooled
// connection over it and was never answered: a link in the frame to the
// same site did nothing for good (bfcache-transport suite). So the
// controller says when its page is back (`lost`), and the next request or
// socket waits for a new transport first. It is built at once when the
// connection had carried something, else on the next request.
import type {
	ProxyTransport,
	RawHeaders,
	TransferrableResponse,
} from '@mercuryworkshop/proxy-transports';
import { wispNote } from './transportLog';

/** the wisp connection under the request is gone (WebTransportCarrierLost: wispWebTransport.ts CARRIER_LOST) */
const DEAD =
	/MuxTaskEnded|Multiplexor task ended|WsImplSocketClosed|MuxMessageFailedTo(?:Send|Recv)|WebTransportCarrierLost/;
/** hyper failed before the request went out (opening its connection) */
const UNSENT = /Error\(Connect,/;
/** the connection closed under a request before its response head */
const LOST =
	/SendRequest|IncompleteMessage|BrokenPipe|broken pipe|connection closed|ConnectionReset|UnexpectedEof/;
/** sent again when the wisp connection is lost under them (no body) */
const REPLAYABLE = new Set(['GET', 'HEAD', 'OPTIONS']);
/**
 * A lost connection, a dead multiplexor found on the way, then the new one,
 * with room for a couple of retries against a server throttling a burst
 * (`backoff` spaces those out).
 */
const ATTEMPTS = 5;

/** how long to wait before trying a throttled request again, growing per attempt (ms) */
const BACKOFF_MS = [50, 120, 250, 500];

/** wait out a throttled retry, resolving early if the request is aborted */
function backoff(
	attempt: number,
	signal: AbortSignal | undefined,
): Promise<void> {
	const ms = BACKOFF_MS[Math.min(attempt, BACKOFF_MS.length) - 1];
	return new Promise((resolve) => {
		if (signal?.aborted) return resolve();
		const done = () => {
			clearTimeout(timer);
			signal?.removeEventListener('abort', done);
			resolve();
		};
		const timer = setTimeout(done, ms);
		signal?.addEventListener('abort', done, { once: true });
	});
}

/** whether `error` says the transport's wisp connection is gone */
export const wispGone = (error: unknown): boolean =>
	DEAD.test(String((error as Error)?.message ?? error));

/** a replayable request waiting for its response head */
interface Waiting {
	generation: number;
	/** give up on this attempt: a new wisp connection is open */
	supersede: () => void;
}

const SUPERSEDED = Symbol('superseded');

/** how long the wisp connection has to open a stream before it counts as lost */
const PROBE_MS = 2000;

/**
 * The wisp close reasons that say the destination cannot be reached at
 * all, whoever asks and however often: 0x42 (holyWisp: a name that does
 * not resolve, an address with no route) and 0x03 (wisp-js's answer to a
 * name that does not resolve). docs/http3.md has the table.
 */
const UNREACHABLE = new Set([0x42, 0x03]);

/** how long the server's answer about a destination is waited for: past every backoff it helps no request */
const ASK_MS = BACKOFF_MS.reduce((sum, ms) => sum + ms);

interface UdpStream {
	read: ReadableStream<unknown>;
	write: WritableStream<unknown>;
	/** the wisp close reason, once `read` has ended (deploy/epoxy patch 0058) */
	closeReason?: () => number | undefined;
}

export default class RevivingTransport implements ProxyTransport {
	#make: () => ProxyTransport;
	#base: ProxyTransport;
	/** bumped each time a new transport replaced the old one */
	#generation = 0;
	#reviving: Promise<boolean> | null = null;
	#waiting = new Set<Waiting>();
	/** the generation whose connection is known gone, until a new transport replaced it */
	#lost = -1;
	/** whether the current generation carried a request or a socket */
	#served = false;
	/** by host and port, the #unreachable question still open: one for a burst */
	#asking = new Map<string, Promise<boolean>>();

	/** `make` builds the transport, and builds it again when its connection is lost */
	constructor(make: () => ProxyTransport) {
		this.#make = make;
		this.#base = make();
	}

	/** the wisp connection is gone (the page is back from the back/forward cache) */
	lost() {
		this.#lost = this.#generation;
		if (this.#served) void this.revive(this.#generation);
	}

	/** a new transport first when the current one's connection is gone */
	async #live(): Promise<number> {
		const generation = this.#generation;
		if (this.#lost === generation) await this.revive(generation);
		this.#served = true;
		return this.#generation;
	}

	/** the transport in use */
	get base(): ProxyTransport {
		return this.#base;
	}

	get ready(): boolean {
		return this.base.ready;
	}
	set ready(value: boolean) {
		this.base.ready = value;
	}

	/** the base transport's client: Http3Transport opens UDP streams on it */
	get client(): unknown {
		return (this.base as { client?: unknown }).client;
	}

	/** what the base sends of the request fields (serveTransport's fitHeaders) */
	get fieldSupport(): unknown {
		return (this.base as { fieldSupport?: unknown }).fieldSupport;
	}

	init(): Promise<void> {
		return this.base.init();
	}

	async meta(): Promise<void> {
		await (this.base as { meta?: () => Promise<void> }).meta?.();
	}

	connect(
		...args: Parameters<ProxyTransport['connect']>
	): ReturnType<ProxyTransport['connect']> {
		const [url, protocols, headers, onopen, onmessage, onclose, onerror] = args;
		const open = (generation: number) =>
			// the socket is the page's to open again; the next one should find a
			// live connection
			this.base.connect(
				url,
				protocols,
				headers,
				onopen,
				onmessage,
				onclose,
				(error) => {
					if (wispGone(error)) void this.revive(generation);
					onerror(error);
				},
			);
		if (this.#lost !== this.#generation) {
			this.#served = true;
			return open(this.#generation);
		}
		// over the new transport once it is up; the page cannot send before
		// its socket opens, so only a close can come first
		type Calls = ReturnType<ProxyTransport['connect']>;
		let calls: Calls | null = null;
		let closed: [number, string] | null = null;
		void this.#live().then((generation) => {
			calls = open(generation);
			if (closed) calls[1](...closed);
		});
		const send: Calls[0] = (data) => calls?.[0](data);
		const close: Calls[1] = (code, reason) => {
			if (calls) calls[1](code, reason);
			else closed = [code, reason];
		};
		return [send, close];
	}

	async request(
		remote: URL,
		method: string,
		body: BodyInit | null,
		headers: RawHeaders,
		signal: AbortSignal | undefined,
	): Promise<TransferrableResponse> {
		// a stream body may be read already; nothing else is consumed by trying
		const resendable = !(body instanceof ReadableStream);
		const replayable =
			REPLAYABLE.has(method.toUpperCase()) &&
			(body === null || body === undefined);
		/** asked once, at the first refused stream: the destination is unreachable */
		let unreachable: Promise<boolean> | null = null;
		for (let attempt = 1; ; attempt++) {
			const generation = await this.#live();
			const pending = this.base.request(remote, method, body, headers, signal);
			let waiting: Waiting | null = null;
			const superseded = replayable
				? new Promise<typeof SUPERSEDED>((resolve) => {
						waiting = { generation, supersede: () => resolve(SUPERSEDED) };
						this.#waiting.add(waiting);
					})
				: null;
			try {
				const result = superseded
					? await Promise.race([pending, superseded])
					: await pending;
				if (result !== SUPERSEDED) return result;
				// an answer that comes after all is not wanted
				pending.then(
					(late) => cancelBody(late),
					() => {},
				);
				if (attempt >= ATTEMPTS || signal?.aborted)
					throw new Error(
						'Stomp: the wisp connection was lost under the request',
					);
			} catch (error) {
				if (attempt >= ATTEMPTS || signal?.aborted) throw error;
				const message = String((error as Error)?.message ?? error);
				let gone = wispGone(error);
				if (!gone && !LOST.test(message)) throw error;
				// A GET whose connection closed before its response head over a
				// wisp connection that looks up: the server's close, which epoxy
				// already sent again where Chrome would, or the wisp connection
				// going with it, which a native connection never sees, so the
				// request goes again over a new one
				if (!gone && replayable && !UNSENT.test(message))
					gone = !(await this.#wispAlive(remote));
				if (gone && !(await this.revive(generation))) throw error;
				if (!(UNSENT.test(message) && resendable) && !(gone && replayable))
					throw error;
				// The connection is still up and the request never went out (a wisp
				// server throttling a burst refuses the extra streams: the stream, and
				// so epoxy's TLS over it, ends before the request is sent). Trying again
				// at once only meets the same full window, so back off a little first and
				// let the streams ahead of it finish. A revived request already waited
				// for the new transport's init, so it is not held up again here.
				// A stream refused because its destination cannot be reached (a
				// name that does not resolve) ends the same way, and Chrome fails
				// that request at once, so the wisp server is asked about the
				// destination beside the first wait, and its answer ends the
				// request where it says unreachable.
				if (!gone) {
					unreachable ??= this.#ask(remote);
					const refused = unreachable.then((yes) =>
						yes ? true : new Promise<never>(() => {}),
					);
					if (
						await Promise.race([
							refused,
							backoff(attempt, signal).then(() => false),
						])
					)
						throw error;
				}
			} finally {
				if (waiting) this.#waiting.delete(waiting);
			}
		}
	}

	/**
	 * Whether the wisp connection still opens a stream. A dead multiplexor
	 * refuses a new one at once (MuxTaskEnded) or never answers; a live one
	 * opens it. The stream asked for is UDP to the request's own host and
	 * port: the wisp server opens a socket and sends nothing on it before
	 * the stream closes again, where a TCP stream would connect to the
	 * server.
	 */
	async #wispAlive(remote: URL): Promise<boolean> {
		const client = this.client as
			{ connect_udp?: (url: string) => Promise<UdpStream> } | undefined;
		if (typeof client?.connect_udp !== 'function') return true;
		const port = remote.port || (remote.protocol === 'https:' ? '443' : '80');
		let timer: ReturnType<typeof setTimeout> | undefined;
		const late = new Promise<'late'>((resolve) => {
			timer = setTimeout(() => resolve('late'), PROBE_MS);
		});
		const opening = client.connect_udp(`udp://${remote.hostname}:${port}`);
		try {
			const stream = await Promise.race([opening, late]);
			if (stream === 'late') {
				opening.then(close, () => {});
				return false;
			}
			close(stream);
			return true;
		} catch (error) {
			if (wispGone(error)) return false;
			// refused (the server relays no UDP there, or none at all): it answered
			return true;
		} finally {
			clearTimeout(timer);
		}
	}

	/** #unreachable, shared by the requests to one host and port while it is open */
	#ask(remote: URL): Promise<boolean> {
		const key = `${remote.hostname}:${remote.port || remote.protocol}`;
		let asking = this.#asking.get(key);
		if (!asking) {
			asking = this.#unreachable(remote).finally(() =>
				this.#asking.delete(key),
			);
			this.#asking.set(key, asking);
		}
		return asking;
	}

	/**
	 * Whether the wisp server says `remote`'s host cannot be reached at
	 * all. Wisp has no answer to CONNECT but a CLOSE, and epoxy ends a TCP
	 * stream the server refused without its reason, which only a UDP stream
	 * reports: the server closes one to such a host as it would the TCP
	 * stream, one wisp round trip after the CONNECT, and leaves one to a
	 * host it can reach open. A refusal for the client's rate (0x49) or a
	 * relay without UDP (0x48) says nothing about the host.
	 */
	async #unreachable(remote: URL): Promise<boolean> {
		const client = this.client as
			{ connect_udp?: (url: string) => Promise<UdpStream> } | undefined;
		if (typeof client?.connect_udp !== 'function') return false;
		const port = remote.port || (remote.protocol === 'https:' ? '443' : '80');
		let timer: ReturnType<typeof setTimeout> | undefined;
		let stream: UdpStream | undefined;
		let reader: ReadableStreamDefaultReader<unknown> | undefined;
		try {
			stream = await client.connect_udp(`udp://${remote.hostname}:${port}`);
			if (typeof stream.closeReason !== 'function') return false;
			reader = stream.read.getReader();
			const read = reader;
			const ended = (async () => {
				while (!(await read.read()).done);
				return true;
			})().catch(() => false);
			const late = new Promise<false>((resolve) => {
				timer = setTimeout(() => resolve(false), ASK_MS);
			});
			if (!(await Promise.race([ended, late]))) return false;
			return UNREACHABLE.has(stream.closeReason() ?? 0);
		} catch {
			return false;
		} finally {
			clearTimeout(timer);
			reader?.cancel().catch(() => {});
			stream?.write.abort().catch(() => {});
			if (stream && !reader) close(stream);
		}
	}

	/**
	 * Build a new transport, unless one was built since `generation` (the
	 * transport a request failed on). Resolves false when the new one could
	 * not start; the next failure tries again.
	 */
	revive(generation: number): Promise<boolean> {
		if (generation !== this.#generation) return Promise.resolve(true);
		this.#reviving ??= (async () => {
			// the host's console (transportLog.ts); the new transport's own
			// notes say what it rides
			wispNote('info', 'reconnecting now (the wisp connection was lost)');
			try {
				const next = this.#make();
				await next.init();
				this.#base = next;
				this.#served = false;
			} catch (error) {
				wispNote(
					'warn',
					`reconnecting failed (${String((error as Error)?.message ?? error).slice(0, 160)}); the next request tries again`,
				);
				return false;
			}
			this.#generation++;
			for (const waiting of this.#waiting)
				if (waiting.generation < this.#generation) waiting.supersede();
			return true;
		})().finally(() => {
			this.#reviving = null;
		});
		return this.#reviving;
	}
}

/** `transport` or the RevivingTransport it wraps (Http3Transport) lost its connection */
export function connectionLost(transport: ProxyTransport | undefined) {
	for (let at = transport; at; at = (at as { base?: ProxyTransport }).base)
		if (at instanceof RevivingTransport) return at.lost();
}

/** close a probe's stream at once, both ways */
function close(stream: UdpStream) {
	stream.read.cancel().catch(() => {});
	stream.write.abort().catch(() => {});
}

function cancelBody(response: TransferrableResponse) {
	const body = response.body as unknown;
	if (body instanceof ReadableStream) body.cancel().catch(() => {});
}
